    [/^CC: regular season finished\. Playoffs start!$/, 'КЧ: регулярка завершена. Плей-офф стартует!'],
    [/^✅ CC (.+):\s+(.+)\s+(\d+)–(\d+)\s+(.+)$/, '✅ КЧ $1: $2 $3–$4 $5'],
    [/^❌ CC (.+):\s+(.+)\s+(\d+)–(\d+)\s+(.+)$/, '❌ КЧ $1: $2 $3–$4 $5'],
    [/^(.+)\s+prize\s+(.+)$/, '$1 призовые $2'],
    [/^ROSTER\s+(.+)$/, 'СОСТАВ $1'],
    [/^Best season:\s*(\d+)\s*\((\d+)th place\)$/, 'Лучший сезон: $1 ($2-е место)'],
    [/^Champions Cup\s+(\d+)$/, 'Кубок Чемпионов $1'],
    [/^CHAMPIONS CUP\s+(\d+)$/, 'КУБОК ЧЕМПИОНОВ $1'],
    [/^Slots for season\s+(\d+)$/, 'Слоты на сезон $1'],
    [/^SLOTS FOR SEASON\s+(\d+)$/, 'СЛОТЫ НА СЕЗОН $1'],
    [/^Showing weeks\s+(\d+)[–-](\d+)$/, 'Показаны недели $1–$2'],
    [/^Conference\s+([A-ZА-Я])$/, 'Конференция $1'],
    [/^CONFERENCE\s+([A-ZА-Я])$/, 'КОНФЕРЕНЦИЯ $1'],
    [/^Group\s+([A-ZА-Я])$/, 'Группа $1'],
    [/^Regular season\s+•\s+Week\s+(\d+)\s*\/\s*(\d+)$/, 'Регулярка • Неделя $1 / $2'],
    [/^Playoffs\s+•\s+Round\s+(\d+)\s*\/\s*(\d+)$/, 'Плей-офф • Раунд $1 / $2'],
    [/^Group stage\s+•\s+Week\s+(\d+)\s*\/\s*(\d+)$/, 'Групповой этап • Неделя $1 / $2']
